from pathlib import Path
import base64,json,html
R=Path(__file__).resolve().parent;A=R/'assets'
def uri(p):
 p=Path(p);return 'data:'+('font/ttf' if p.suffix=='.ttf' else 'image/png')+';base64,'+base64.b64encode(p.read_bytes()).decode()
def txt(s):return html.escape(s)
def svg(s,w=1600,h=600):return f'<svg viewBox="0 0 {w} {h}" xmlns="http://www.w3.org/2000/svg" role="img">{s}</svg>'
def label(x,y,t,size=25,color='#70685f',anchor='middle'):return f'<text x="{x}" y="{y}" font-family="inherit" font-size="{size}" fill="{color}" text-anchor="{anchor}">{txt(t)}</text>'
def line(x,y,a,b,c='#c7bcb0',dash=''):return f'<path d="M{x} {y} L{a} {b}" stroke="{c}" stroke-width="2" fill="none" stroke-dasharray="{dash}"/>'
def circle(x,y,r,c):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{c}"/>'
def rat(x=0,y=0,scale=1,color='#f1d997',arms=False,finger=False):
 finger_layer='<rect x="-18" y="153" width="36" height="135" rx="18" fill="#e4b49b"/>' if finger else ''
 return f'<g transform="translate({x} {y}) scale({scale})"><path d="M85 240 Q155 300 160 250" stroke="{color}" stroke-width="18" fill="none" stroke-linecap="round"/><ellipse cx="0" cy="165" rx="82" ry="105" fill="{color}"/><ellipse cx="0" cy="185" rx="57" ry="72" fill="#fffcf3"/><circle cx="-73" cy="-9" r="49" fill="{color}"/><circle cx="73" cy="-9" r="49" fill="{color}"/><circle cx="-73" cy="-9" r="35" fill="#edc8c4"/><circle cx="73" cy="-9" r="35" fill="#edc8c4"/><ellipse cx="0" cy="54" rx="94" ry="76" fill="{color}"/><ellipse cx="0" cy="83" rx="50" ry="33" fill="#fff9ef"/><ellipse cx="-33" cy="48" rx="6" ry="9" fill="#504942"/><ellipse cx="33" cy="48" rx="6" ry="9" fill="#504942"/><ellipse cx="0" cy="76" rx="9" ry="6" fill="#e8aeb6"/><ellipse cx="-58" cy="76" rx="14" ry="8" fill="#efd0c6"/><ellipse cx="58" cy="76" rx="14" ry="8" fill="#efd0c6"/>{finger_layer}<path d="M-68 132 Q-100 170 {-24 if arms else -100} 185 M68 132 Q100 170 {24 if arms else 100} 185" stroke="{color}" stroke-width="19" fill="none" stroke-linecap="round"/><ellipse cx="{-24 if arms else -100}" cy="185" rx="20" ry="13" fill="#efc7c9"/><ellipse cx="{24 if arms else 100}" cy="185" rx="20" ry="13" fill="#efc7c9"/><ellipse cx="-51" cy="258" rx="34" ry="14" fill="#efc7c9"/><ellipse cx="51" cy="258" rx="34" ry="14" fill="#efc7c9"/></g>'
def icon(name,x,y,s=1):
 names={'BOCCO':'bocco','Qoobo':'qoobo','HAM HAM':'hamham','FuFu':'fufu','Mirumi':'mirumi'}
 f=A/(names[name]+'.png')
 if f.exists():return f'<g transform="translate({x} {y}) scale({s})"><image href="{uri(f)}" x="-125" y="-95" width="250" height="190" preserveAspectRatio="xMidYMid meet"/></g>'
 shapes={
 'Qoobo':'<ellipse cx="0" cy="15" rx="83" ry="55" fill="#d9d5cf"/><path d="M60 38 Q150 70 125 -20" fill="none" stroke="#b9b5ae" stroke-width="25" stroke-linecap="round"/>',
 'BOCCO':'<rect x="-44" y="-55" width="88" height="80" rx="40" fill="#e4d8c3"/><path d="M-55 90 Q-55 5 0 8 Q55 5 55 90Z" fill="#f2e8d7"/><circle cx="-17" cy="-20" r="5" fill="#655c54"/><circle cx="17" cy="-20" r="5" fill="#655c54"/><circle cy="62" r="13" fill="#eb8a68"/>',
 'HAM HAM':'<ellipse cy="25" rx="65" ry="67" fill="#e6dbcb"/><circle cx="-45" cy="-35" r="23" fill="#e6dbcb"/><circle cx="45" cy="-35" r="23" fill="#e6dbcb"/><circle cx="-21" cy="8" r="4" fill="#665e56"/><circle cx="21" cy="8" r="4" fill="#665e56"/><ellipse cy="40" rx="18" ry="10" fill="#ca9f9d"/>',
 'FuFu':'<path d="M-65 75 Q-70 -40 0 -48 Q70 -40 65 75Z" fill="#ddcdbb"/><circle cx="-18" cy="-4" r="4" fill="#665e56"/><circle cx="18" cy="-4" r="4" fill="#665e56"/><ellipse cy="22" rx="8" ry="12" fill="#927964"/><path d="M-25 110 Q10 80 40 110 M-5 130 Q25 100 60 130" stroke="#a6c7d4" stroke-width="3" fill="none"/>',
 'Mirumi':'<ellipse cy="27" rx="65" ry="73" fill="#cfc9c3"/><ellipse cy="-26" rx="76" ry="58" fill="#d8d2cc"/><circle cx="-28" cy="-27" r="24" fill="#faf5e9"/><circle cx="28" cy="-27" r="24" fill="#faf5e9"/><circle cx="-23" cy="-28" r="9" fill="#504943"/><circle cx="23" cy="-28" r="9" fill="#504943"/><path d="M-45 42 Q-95 90 -72 120 M45 42 Q95 90 72 120" stroke="#cfc9c3" stroke-width="20" fill="none" stroke-linecap="round"/>'}
 return f'<g transform="translate({x} {y}) scale({s})">{shapes[name]}</g>'
def cards(items,cls=''):
 return '<div class="cards '+cls+'">'+''.join(f'<article><span class="num">{n}</span><h3>{h}</h3><p>{p}</p></article>' for n,h,p in items)+'</div>'
def photo(key,cls='',alt='鼠大产品概念图'):
 return f'<img class="photo {cls}" src="@@{key}@@" alt="{alt}">'
slides=[]
def add(tag,title,body,note='',cls='',foot=''):
 slides.append(dict(tag=tag,title=title,body=body,note=note,cls=cls,foot=foot))
add('SUDA / DESIGN MANAGEMENT','鼠大 / SUDA',photo('cover','cover','鼠大封面：黄白花枝鼠抱住用户手指'),'开场先让观众记住动作：捏一下，它就抱住你。本案是设计管理课程中的校园纪念品产品提案；苏大与品牌均未授权，图片是AI概念可视化，并非实物照片。','cover-slide')
add('01 / PROJECT IN ONE MINUTE','把校园身份，变成一次被抱住的记忆。',cards([('发现','有符号，少行为','常见纪念品便于识别，却缺少一次可演示的互动。'),('机会','触觉是入口','把校园情感放进一件可以揉、抱、带走的小物。'),('决策','只保留拥抱','从多功能探索，收敛到一个清楚的拟生动作。'),('产品','鼠大 / SUDA','捏压腹部，前爪抱住手指，手动掰开释放。')])+ '<div class="statement">发现 → 机会 → 决策 → 产品</div>','这是一条决策链，而非公司介绍。第一步是研究假设，后续必须以学生访谈、样机体验与付费意愿测试验证。设计总监负责让用户价值、机构可行性和成本约束指向同一个动作。')
add('','','','此页按要求完全留白，供汇报人插入角色介绍图片。','blank')
add('02 / BENCHMARK','Yukai 把机器人，放进轻松的日常。','<div class="split"><div><div class="bigword">Robotics<br>for Fun Living</div><p class="lead">以有趣的身体行为，降低人与机器的距离。</p><div class="pill">研究对象：行为与情感的关系</div></div><div class="product-trail">'+svg(''.join(icon(n,150+i*230,180,.8)+label(150+i*230,335,n,23) for i,n in enumerate(['BOCCO','Qoobo','HAM HAM'])),800,440)+'<p>沟通入口 → 触觉安抚 → 细小拟生反应</p></div></div><div class="milestones">代表产品线索：BOCCO → Qoobo → AMAGAMI HAM HAM → Nékojita FuFu / Mirumi</div>','品牌口号与产品名称用于建立研究对象。此处展示代表产品的发展线索，不作为逐年发布年表。已核对官方产品页的五款产品与行为描述；本页按体验演进组织，不以页面上传路径推断上市年份。下页开始的象限与分类是本项目的设计研究解读。',foot='资料：Yukai Engineering 官方产品页 · 图片版权归原权利人')
add('02 / PRODUCT MATRIX','陪伴不只一种，但每件产品都有明确入口。',svg(line(200,490,1500,490)+line(200,490,200,50)+label(1450,545,'独立的日常行为',25)+label(220,35,'直接身体接触',25)+label(340,570,'沟通 / 信息',25)+label(60,480,'环境',24)+''.join(icon(n,x,y,.62)+label(x,y+100,lab,24) for n,x,y,lab in [('BOCCO',390,365,'BOCCO · 家庭沟通'),('Qoobo',700,160,'Qoobo · 抚摸摇尾'),('HAM HAM',1070,120,'AMAGAMI HAM HAM · 轻咬'),('FuFu',1270,365,'Nékojita FuFu · 吹气'),('Mirumi',830,350,'Mirumi · 偷瞄')])), '矩阵把产品按互动入口与身体接触关系分组，不是统计测量。BOCCO承担家庭沟通，其他代表产品把感知集中到某个生活动作；我们重点借鉴后者的清晰程度，而非照搬机构。',foot='定性研究矩阵 · 位置为设计团队判断 · 图片：Yukai Engineering')
add('02 / ONE CLEAR BEHAVIOR','最有辨识度的产品，只有一个清楚的行为。','<div class="behavior-grid">'+''.join('<div>'+svg(icon(n,160,125,1.0),320,260)+f'<small>{lab}</small><h3>{b}</h3></div>' for n,lab,b in [('Qoobo','Qoobo','摇尾'),('HAM HAM','AMAGAMI HAM HAM','轻咬'),('FuFu','Nékojita FuFu','吹气'),('Mirumi','Mirumi','偷瞄')])+'</div><div class="statement">不是记住功能清单，而是记住它做了什么。</div>','代表行为用于解释品牌的产品识别方式。每件产品可能有多种内部逻辑和操作，本页强调用户首先感知到的动作，不主张其真实功能仅有一种。',foot='行为归纳 · 产品图来源：Yukai Engineering 官方产品页')
add('02 / DESIGN LANGUAGE','技术退后一点，触感就能走近一点。','<div class="language-layout"><div class="word-stack">ONE ACTION<br>LESS UI<br>MORE TOUCH</div><div>'+cards([('01','单一行为','先让人看懂，再让人喜欢。'),('02','弱 UI / 低技术感','不让屏幕与操作步骤成为主角。'),('03','拟生反应 / 触觉优先','回应身体，而不是增加通知。')])+'</div></div>','这里的低技术感描述用户体验，不代表内部技术简单。鼠大转译的是体验原则：让动作可解释、触觉优先；其机械方案仍需工程验证。')
add('02 / EMOTIONAL INTERACTION','围绕情绪，产品自然进入不同日常。',svg(''.join(line(800,300,x,y) for x,y in [(300,130),(1300,130),(260,460),(1340,460)])+circle(800,300,150,'#f2d6c9')+label(800,290,'Emotional',34)+label(800,338,'Interaction',34)+''.join(circle(x,y,90,c)+label(x,y-8,t,27)+label(x,y+31,p,21) for x,y,c,t,p in [(300,130,'#e7e1d2','家庭沟通','BOCCO'),(1300,130,'#dce8eb','触觉陪伴','Qoobo / HAM HAM'),(260,460,'#f5e1dd','生活微动作','FuFu'),(1340,460,'#e6e3db','随身回应','Mirumi')])), '生态图是按使用关系建立的研究图，不表示设备互联或官方产品架构。鼠大的位置是随身与触觉的交叉：校园纪念品通过单一动作进入日常。',foot='使用关系图 · 不表示设备互联')
add('02 / POSITIONING','鼠大要进入“低技术感、高情绪价值”的一侧。',svg('<rect x="210" y="50" width="590" height="260" rx="30" fill="#f2dfd1"/>'+line(200,530,1500,530)+line(200,530,200,35)+line(800,530,800,35,'#d8cfc5','6 10')+line(200,310,1500,310,'#d8cfc5','6 10')+label(250,25,'高情绪价值',26,'#df7957','start')+label(1400,580,'高技术感',26)+label(300,580,'低技术感',26)+label(120,530,'低',24)+circle(540,175,67,'#d8e4e6')+label(540,184,'Yukai*',28)+circle(360,105,48,'#e89772')+label(360,114,'鼠大',26,'#fff')+circle(1120,190,36,'#dedbd6')+label(1120,251,'多功能陪伴设备',24)+circle(460,420,32,'#dedbd6')+label(460,480,'普通纪念物',24)), '象限是提案的目标定位而非客观评分。Yukai各产品有差异，这里只概括其触觉陪伴代表产品的体验气质。鼠大能否提供高情绪价值，必须用用户实验验证。',foot='* 指 Yukai 触觉陪伴代表产品；位置为定性假设')
add('03 / CAMPUS OPPORTUNITY','校园纪念品有身份符号，却很少有行为记忆。','<div class="object-row">'+''.join(f'<div><div class="object-symbol">{s}</div><h3>{t}</h3><p>{p}</p></div>' for s,t,p in [('◎','校徽','身份明确'),('⌁','钥匙扣','便于携带'),('♡','普通毛绒','亲近、可触摸'),('↔','互动玩具','动作容易被记住')])+'</div><div class="statement">机会：让“这是我的学校”，变成“它会抱住我”。</div>','这是校园纪念品研究的初步观察，并非对所有学校商品的普查结论。后续应抽样校内文创商店与线上售卖页面，核实互动型商品覆盖情况。')
add('03 / WHO IT IS FOR','先服务想把校园带在身边的人。','<div class="split"><div class="persona"><span>18–25</span><h3>在校大学生 / 年轻校友</h3><p>背包通勤 · 宿舍陪伴 · 毕业送礼</p><div class="pill">“我想带走一点校园，也想随手摸到它。”</div><small>假设性用户画像，非访谈原话</small></div>'+photo('backpack','','背包肩带上的小尺寸鼠大')+'</div>','核心对象为18至25岁在校学生和年轻校友，不代表已完成真实访谈。至少覆盖日常自用、毕业纪念、朋友互赠三类动机；验证时分别观察动作理解、携带负担和付费意愿。',foot='人物与场景为 AI 概念图 · 用户画像待验证')
add('03 / USER JOURNEY','让第一次触摸，自然接到下一次分享。','<div class="journey">'+''.join(f'<div><b>{i:02}</b><h3>{h}</h3><p>{p}</p></div>' for i,(h,p) in enumerate([('看到','耳朵与黄白配色'),('摸到','腹部柔软可捏'),('购买','一次演示看懂'),('使用','抱住我的手指'),('携带','抱在背包肩带'),('合影','双鼠尾巴成心'),('分享','一句话说清动作')],1))+'</div><div class="soft-strip"><strong>关键转化点：摸到 → 看懂拥抱 → 愿意带走</strong><span>门店演示、包装动图、可触摸样机共同服务这一刻。</span></div>','旅程是拟定体验路径。样机测试时分别记录第一次触摸前后、演示前后的反应，不以社交分享意愿代替真实购买，也不把点赞当成市场规模。')
add('03 / PRIORITY','先满足互动记忆、校园识别与随身携带。',svg(line(230,510,1450,510)+line(230,510,230,50)+label(1410,565,'开发投入 →',25)+label(230,30,'用户价值 ↑',25,'#70685f','start')+'<rect x="260" y="60" width="650" height="230" rx="36" fill="#f0dfd1"/>'+''.join(circle(x,y,r,c)+label(x,y+8,t,26) for x,y,r,c,t in [(420,135,74,'#e9be9e','互动记忆'),(660,125,69,'#f1dba5','校园识别'),(540,280,65,'#d6e3e5','随身携带'),(1040,240,58,'#e6d6db','尾巴磁吸'),(1250,390,63,'#e3ded5','多种电子功能')])+label(1060,82,'先做 / 后做 / 不做',27)), '气泡大小只表示讨论时的相对关注度，没有定量研究基础。互动动作、IP识别和尺寸是首版必须验证的三项；尾部磁吸为次级体验，成本或安全不成立时可延后。电子功能不进入当前版本。',foot='优先级为设计假设 · 非用户调查数据')
add('03 / COMPETITIVE SET','鼠大的差异，是让互动与校园身份同时成立。','<div class="comparison"><div class="table-row th"><span>类型</span><span>校园识别</span><span>动作记忆</span><span>随身携带</span><span>触感陪伴</span></div>'+''.join('<div class="table-row '+('highlight' if n=='鼠大 / 目标' else '')+'"><strong>'+n+'</strong>'+''.join('<span class="dot '+v+'">'+{'yes':'●','mid':'◐','no':'○'}[v]+'</span>' for v in vals)+'</div>' for n,vals in [('普通校园毛绒',['yes','no','mid','yes']),('磁吸玩偶',['mid','mid','yes','yes']),('魔术贴玩偶',['mid','mid','yes','mid']),('Yukai 代表产品',['no','yes','mid','yes']),('鼠大 / 目标',['yes','yes','yes','yes'])])+'</div><div class="legend">● 典型优势　◐ 因产品而异　○ 通常不突出　／　鼠大一行为设计目标</div>','按类别而非具体SKU比较，不能用于证明所有竞品均不具备某特征。鼠大一行是目标，不是已验证优势。实测应选同价格带和相近尺寸的样品，补充价格、洗护、重量与耐久度。',foot='定性类别比较 · 未进行实物横评')
add('03 / THE GAP','空白在两者之间：有身份，也有一个生命行为。','<div class="gap"><div><small>CAMPUS IP</small><h3>校园 IP 毛绒</h3><p>“它属于我的学校。”</p></div><div class="gap-center">＋<strong>鼠大</strong><span>低技术感 × 拟生行为</span></div><div><small>EMOTIONAL TOY</small><h3>情绪互动玩具</h3><p>“它好像在回应我。”</p></div></div><div class="statement">这是一处值得验证的机会缺口，不是已证明的无人市场。</div>','真正的问题不是是否存在世界上完全相同的商品，而是校园渠道的目标用户是否愿意为明确、可触摸的动作多付一点成本。必须同时验证校园授权、用户需求及机构可制造性。')
add('04 / WHY SUDA','从“苏大”到“鼠大”，名字先带来亲近感。','<div class="name-chain"><div>苏大<small>校园身份</small></div><i>→</i><div>鼠大<small>谐音记忆</small></div><i>→</i><div>鼠类 IP<small>大耳 · 小手</small></div><i>→</i><div class="rat-end">'+svg(rat(150,55,.65),300,280)+'<small>花枝鼠 / 亲近触感</small></div></div><div class="soft-strip">校园识别由名字、包装和授权视觉承担；柔软体态负责让人靠近。</div>','花枝鼠是宠物大鼠的俗称，本案为其拟人化毛绒设计。避免直接等同实验动物或普通卡通老鼠。苏大谐音只是命名提案，校名、校徽与文创销售须事先获得学校相应授权。五色与学士服领色仅作为纪念关联线索，需核对校方规范，不承诺学科一一对应。')
add('04 / CORE CONCEPT','捏一下，它就抱住你。','<div class="concept"><div class="bigword">SQUEEZE<br>TO HUG.</div>'+svg(rat(380,100,1.8,arms=True),800,650)+'</div><p class="concept-caption">它没有很多功能。它只是会抱住你。</p>','第一记忆点只有捏压拥抱。交互目标是腹部受压后前爪内合，撤去按压仍保持，再由用户主动掰开释放。图中为造型与动作示意，不代表机构已经验证。',foot='交互与结构为待验证设计方案')
add('04 / INTERACTION','松开腹部后，它也暂时不松手。','<div class="interaction">'+''.join('<div>'+svg(rat(150,55,.68,arms=a,finger=(a or h=='SQUEEZE')),300,300)+f'<h3>{h}</h3><p>{p}</p></div>' for h,p,a in [('NORMAL','前爪张开',False),('SQUEEZE','捏压白色腹部',False),('HUG','前爪向内闭合',True),('HOLD','撤去按压仍抱住',True)])+'</div><div class="release">SQUEEZE → HUG → HOLD → <b>RELEASE</b><span>用户主动掰开前爪，完成释放与复位。</span></div>','四格与用户给定NORMAL-SQUEEZE-HUG-HOLD一致，底部补全RELEASE，避免把保持与释放混淆。闭合、保持和手动释放都需在独立机构样机上演示。抱持不是强夹持，要验证舒适性、快速逃脱、夹点与过载行为。')
add('04 / TOUCH','被一只小鼠抱住，就够了。','<div class="photo-split"><div><div class="bigword">WITH<br>YOU.</div><p>巴掌大小。<br>手指轻压腹部，前爪向内拥抱。</p><small>交互目标：撤去按压后仍保持，手动掰开释放。</small></div>'+photo('touch','','女大学生手持鼠大，另一只手指轻压腹部并被前爪抱住')+'</div>','场景图延续封面造型。图像只用于说明交互目标，不能证明机构已实现。实际测试要观察用户是否自然找到腹部、能否独立完成按压和释放，过程中是否感觉被夹或难以脱开。',foot='AI 场景概念图 · 非实物或性能证明')
add('04 / TRAVEL','让陪伴，跟着背包一起出门。','<div class="wide-photo">'+photo('backpack')+'<div class="photo-label"><span>TRAVEL</span><p>两只前爪抱住肩带。<br>小尺寸，才愿意每天带着。</p></div></div>','肩带场景复用前爪行为，不另加一套交互。该场景对闭合行程和抱持力提出额外约束：需要分别测不同肩带厚度、走动振动、意外拉扯和脱落。正式商品可评估隐藏式保险挂环，但不能用它掩盖拥抱机构失败。',foot='AI 场景概念图 · 肩带适配与防脱性能待验证')
add('04 / TOGETHER','靠近一点，尾巴就连成一颗心。','<div class="wide-photo">'+photo('tails','','黄鼠与灰鼠背面，短毛绒尾巴磁吸形成爱心')+'<div class="photo-label right"><span>TOGETHER</span><p>黄鼠是黄尾巴，灰鼠是灰尾巴。<br>短、圆、柔软；社交体验保持轻量。</p></div></div>','尾巴磁吸为次级社交体验，服务合影和互赠，不替代核心拥抱。心形需要预成型软支撑与磁极方向配合，不能假定软尾巴靠磁铁就会自动成心。磁体应不可拆取并可靠封装，验证拉脱、吞咽、洗护及磁极配对风险。',foot='AI 形态概念图 · 尾巴成形与磁体安全待验证')
add('04 / FAMILY','同一只鼠，装下五种校园心情。','<div class="family-photo">'+photo('family','','黄粉灰白柔红五色鼠大同款并排')+'</div><div class="color-row">'+''.join(f'<span><i style="background:{c}"></i>{n}</span>' for n,c in [('黄白 / ORIGINAL','#edda9e'),('粉 / PINK','#e9c8cb'),('灰 / GREY','#bdbbb7'),('白 / WHITE','#f1ede2'),('柔红 / RED','#bf7874')])+'</div><p class="family-note">后四色作为学士服领色的纪念联想；具体对应以校方规范与授权为准。</p>','先用黄白主色验证一套版型和机构，再扩展粉灰白柔红，减少多SKU并行带来的库存与一致性风险。领色关联是设计叙事，不应宣称其与所有院系官方领色一一对应。',foot='AI 配色概念图 · 颜色打样与校方规范待确认')
add('04 / A LITTLE FAMILY','装进帆布包，也装进一起毕业的记忆。','<div class="wide-photo">'+photo('bag','','五色鼠大趴在帆布包里，面朝镜头，小手扒住包口')+'<div class="photo-label"><span>FAMILY</span><p>一只自用，两只互赠。<br>五色是选择，不是五套新功能。</p></div></div>','包内合影场景把配色与朋友关系连接。商业上并不建议首批同时大量生产五色，应在样品体验中记录颜色偏好，再决定先上主色和最有需求的一款扩展色。',foot='AI 生活方式概念图')
add('04 / CMF','让人想反复捏的，是材质的松弛感。','<div class="cmf"><div class="detail-photo">'+photo('touch')+'</div><div class="cmf-list"><article><span>Fine Fur</span><h3>细软短绒</h3><p>自然毛流，保留耳、鼻与脸部轮廓。</p></article><article><span>Beanbag Body</span><h3>饱满，却不僵硬</h3><p>下腹独立豆袋，上腹留出机构空间。</p></article><article><span>Soft Touch</span><h3>耳内、掌心、脚尖轻轻带粉</h3><p>白色嘴筒与肚皮用柔和渐变衔接。</p></article></div></div>','CMF意向需与工厂验证：渐变效果可比较喷染、分区绒料或印花，优先低转移、低色差的可量产方式。颗粒填充要独立双层内袋，不能进入机构；明确填料材质、可追溯性和洗护方式，避免对手感或安全作未经测试的承诺。',foot='材质意向 · 绒料、渐变工艺与填充规格待打样')
add('04 / STRUCTURE','拥抱需要一条独立、可保持的机械路径。',svg('<path d="M410 50 L410 560" stroke="#c8beb2" stroke-dasharray="6 10" stroke-width="2"/>'+''.join(f'<ellipse cx="410" cy="{y}" rx="{rx}" ry="{ry}" fill="{c}" stroke="#c8beb2" stroke-width="2"/>'+line(410+rx,y,900,y)+label(930,y+9,t,26,'#70685f','start') for y,rx,ry,c,t in [(75,195,42,'#f1d997','外部绒布 / 内衬：亲肤接触层'),(170,150,30,'#e4e7e2','上半身框架：隔离手指可触及夹点'),(255,110,24,'#f2d7cb','腹部挤压板：接收捏压力'),(340,135,23,'#cddfe4','连杆 → 前爪：把按压转成内合'),(425,115,25,'#e3d3d9','越中心保持 / 可回掰释放：候选机构'),(525,160,40,'#e7dfc9','下腹豆袋：密封内袋，远离传动')])+label(1260,545,'尾部磁吸：独立封装模块',25)+label(410,610,'概念爆炸示意 / 非工程图',22)), '不能把普通挤压连杆直接当成能保持的机构。候选路径为腹部板驱动连杆，经过越中心弹性保持；掰开前爪反向复位。它可能出现锁死、力突变、寿命不足、影响豆袋手感等问题，必须先做无绒布机构样机。另比较弹性双稳态与摩擦保持，选择能稳定保持且轻松脱开的方案。所有行程、材料、夹持力与尺寸均未冻结。',foot='概念结构 · 保持、释放、夹力与寿命均待工程验证')
add('05 / AI DESIGN EXECUTION','AI 产出候选，人负责证据与取舍。',cards([('Research','研究助理','交付：产品与行为索引；验收：每条事实可追溯。'),('Concept','概念设计师','交付：统一造型与场景；验收：比例、耳鼻、色彩一致。'),('Structure','结构助理','交付：机构候选与风险；验收：由工程样机证实。'),('Visual','视觉设计师','交付：讲解图与品牌页面；验收：结论清楚、假设可见。')])+ '<div class="soft-strip"><strong>设计总监的门槛：来源、造型、机构、成本，四道验收。</strong><span>本轮已完成 AI 场景与页面执行；品牌产品已核对官方总览；用户研究与机构性能仍待验证。</span></div>','AI员工是分工比喻，不表示使用了真实员工或已完成工程工作。本轮实际执行为资料访问尝试、统一参考图的场景生成、图解与HTML制作；已核验官方产品总览的行为描述与产品图，独立产品站点仍需逐项补查。Research卡描述后续验收要求，Structure卡的产出只是机构候选。设计总监对证据、授权、安全和选型承担责任。')
add('05 / LESS BUT STRONGER','不断删减，才留下最强的那个动作。','<div class="iteration">'+''.join(f'<div class="step {"final-step" if i==4 else ""}"><b>0{i+1}</b><h3>{h}</h3><p>{p}</p></div>' for i,(h,p) in enumerate([('晚安海豹','探索安抚与陪伴'),('旅行陪伴','转向随身场景'),('花枝鼠','建立校园命名与体态'),('多交互探索','减少机构与记忆负担'),('捏压拥抱','保留可演示的第一动作')]))+'</div><div class="statement">删去的是功能数量，留下的是行为辨识度。</div>','此时间线依据用户给定的概念演进顺序整理，不代表已有历史原型或用户测试记录。为可追溯管理，每次迭代应保存日期、关键假设、样机证据与淘汰原因。下一步不是继续加功能，而是验证抱持机构。',foot='概念演进复盘 · 未提供历史样机与实验数据')
add('05 / PILOT TO LAUNCH','先验证拥抱，再决定值不值得量产。','<div class="business"><div><div class="roadmap"><div><b>G0 / 1–2周</b><strong>需求与授权</strong><span>访谈、校方边界、竞品样品</span></div><div><b>G1 / 3–5周</b><strong>机构样机</strong><span>闭合、保持、释放、安全</span></div><div><b>G2 / 6–8周</b><strong>单色小批试产</strong><span>成本、耐久、真实体验</span></div><div><b>G3 / 9–12周</b><strong>校园试售</strong><span>先主色，再决定五色扩展</span></div></div><div class="costs"><b>成本核算路径</b><p>绒布缝制 + 机构装配 + 填充 + 磁体封装 + 包装 + 测试 / 授权 / 损耗 / 渠道</p><span>获取工厂报价后倒推可售价格；用两档真实报价做价格接受度测试。</span></div></div><div class="kpi"><small>待验证假设 / 建议验收门槛</small><h3>先过门槛，再开下一阶段。</h3><p>动作理解：≥ 80% 无提示完成捏压与释放</p><p>可靠性：目标 1,000 次循环后仍闭合、保持与释放</p><p>安全：夹点、磁体与填充封装不通过即暂停</p><p>商业：扣除全成本及渠道后，试售贡献毛利为正</p><div class="pill">核心风险：锁死 / 脱落 / 误吞 / 授权 / 成本超标</div></div></div>','所有周数、百分比和循环次数都是建议计划或验收门槛，不是实测数据。建议先招募12至20名目标用户探索需求，G1以多只独立样机测试同一流程，G2试产数量由工厂MOQ和损耗预算决定。1,000次仅是内部初步目标，不能代替适用安全标准的检测。价格测试需在成本报价后确定候选售价，分别记录真实购买与口头意愿。渠道包括校方授权门店和毕业季快闪，未取得合作。各阶段只有对应门槛达标才推进；低于毛利门槛应先改设计与采购而非盲目涨价。',foot='全部为待验证假设 · 无销量、成本或市场规模实测数据')
add('06 / THE DECISION','先做一只会抱住你的鼠。','<div class="decision"><div class="bigword">ONE HUG.<br>THAT’S IT.</div><div>'+cards([('01','只保留最强动作','先把捏压、保持、释放做可靠。'),('02','先做一色、一套机构','把授权、触感与安全一起验证。'),('03','用证据决定下一步','用户愿带、工厂能做、试售算得过账，再扩展。')])+'</div></div><p class="closing-line">而不是一只功能很多的电子玩具。</p>','设计总监的最终决策是冻结首版范围，但不提前宣称成功。当前可以批准机构验证与单色造型打样，不应批准未经验证的量产。校方授权、安全检测、用户接受度和完整成本核算是放量前置条件。')
add('06 / THANK YOU','它只是会抱住你。','<div class="sources"><div class="bigword">THANK<br>YOU.</div><div><h3>Sources / 研究入口</h3><a href="https://www.ux-xu.com/products/" target="_blank" rel="noopener">Yukai Engineering / 官方产品总览</a><a href="https://qoobo.info/" target="_blank" rel="noopener">Qoobo / 摇尾陪伴</a><a href="https://hamham.ux-xu.com/" target="_blank" rel="noopener">AMAGAMI HAM HAM / 轻咬</a><a href="https://nekojitafufu.ux-xu.com/" target="_blank" rel="noopener">Nékojita FuFu / 吹气</a><a href="https://mirumi.tokyo/" target="_blank" rel="noopener">Mirumi / 随身反应</a><small>品牌行为与产品图已核对 Yukai 官方产品总览；查阅日期：2026.10.21。</small><small>鼠大图像：AI 概念可视化；品牌产品图：Yukai Engineering 官方产品总览。<br>校园授权、用户画像、市场定位、结构与商业指标均按提案假设处理。<br>页面实现：Frontend Slides · github.com/zarazhangrui/frontend-slides</small></div></div>','结束时回到动作，而不是功能清单。已读取Yukai官方产品总览，确认家庭沟通、摇尾、轻咬、吹气及偷瞄的代表行为；部分独立产品站点为脚本页面或失效链接，优先以官方总览为准。本轮未提供独立用户调查或已量产证据。汇报前应补充校方授权依据、官方产品信息、真实机构样机视频和用户验证结果。')

